// AP Physics 1 Practice Exam 1. 42 multiple choice across all eight units, then MR (10), TBR (12), EDA (10), QQT (8) = 40 points.
import { graph } from "../../plot.js";
import { scene, incline } from "../../diagrams.js";
const R = String.raw;
const one = (blocks, title = "") => [{ title, blocks }];
const cosInterp = (xs, hs, x0, sc, y0) => { // smooth track through nodes (flat at each node)
  const pts = [];
  for (let i = 0; i < xs.length - 1; i++) for (let j = 0; j <= 12; j++) { const s = j / 12; pts.push([xs[i] + s * (xs[i + 1] - xs[i]), y0 + sc * (hs[i] + (hs[i + 1] - hs[i]) * (1 - Math.cos(Math.PI * s)) / 2)]); }
  return pts;
};

