const roverG = graph({ width: 400, height: 250, x: [0, 12], y: [-2, 4], step: { x: 1, y: 1 }, xname: "t (s)", yname: "v (m/s)", segments: [[0, 0, 3, 3], [3, 3, 7, 3], [7, 3, 10, 0], [10, 0, 12, -1]],
  alt: "Velocity versus time for a lunar rover. The velocity rises in a straight line from 0 at 0 seconds to 3 meters per second at 3 seconds, stays at 3 meters per second until 7 seconds, falls in a straight line to 0 at 10 seconds, and continues falling to negative 1 meter per second at 12 seconds." });
// m15, m16: F versus x for a trolley
const trolG = graph({ width: 400, height: 250, x: [0, 5], y: [0, 12], step: { x: 1, y: 2 }, xname: "x (m)", yname: "F (N)", segments: [[0, 0, 1, 10], [1, 10, 3, 10], [3, 10, 4, 0]],
  alt: "Net force versus position for a trolley. The force rises in a straight line from 0 newtons at 0 meters to 10 newtons at 1.0 meter, stays at 10 newtons until 3.0 meters, and falls in a straight line to 0 newtons at 4.0 meters." });
// m27: omega versus t for a hard drive platter
